        nr=sc_=(sr+1 if sr<drow else sr-1, sc)
        out[sr][sc]=0; out[nr[0]][nr[1]]=4
        for dr,dc in ((-1,-1),(-1,1)):
            r,c=nr[0]+dr,nr[1]+dc
            while 0<=r<h and 0<=c<w and r not in div and g[r][c]==0:
                out[r][c]=4; r+=dr; c+=dc
    return out
